window.STORY_CHAPTERS["c7ee04fa8aacbf070"]={"id":"c7ee04fa8aacbf070","lines":[{"uid":"talk.edith_1_00#originalText","id":"talk.edith_1_00","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"「视情况」","en":"It Depends","ja":"「場合によっては」"},"kind":"caption"},{"uid":"talk.edith_1_01#originalText","id":"talk.edith_1_01","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我回来了──","en":"I'm home...","ja":"ただいまー"},"kind":"dialogue"},{"uid":"talk.edith_1_02#originalText","id":"talk.edith_1_02","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"喔，伊迪丝。欢迎回来。","en":"Hi, Eydis.","ja":"お、イーディスお帰り"},"kind":"dialogue"},{"uid":"talk.edith_1_03#originalText","id":"talk.edith_1_03","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"哇，桐人。什么风把你吹来了？","en":"Oh, Kirito? I don't usually see you here.","ja":"あら、キリトここにいるなんて珍しいじゃない"},"kind":"dialogue"},{"uid":"talk.edith_1_04#originalText","id":"talk.edith_1_04","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"正好刚结束工作，所以就来了。啊──好累。","en":"I just finished my work. Ahhh, I'm exhausted.","ja":"ちょうど仕事が終わった所なんだよあー、疲れた"},"kind":"dialogue"},{"uid":"talk.edith_1_05#originalText","id":"talk.edith_1_05","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"偶尔也得表现得像个代表剑士嘛～","en":"You have to do what's expected of you as the swordsman delegate sometimes, you know.","ja":"たまには、代表剣士らしいこともしないとねー"},"kind":"dialogue"},{"uid":"talk.edith_1_06#originalText","id":"talk.edith_1_06","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"法那提欧小姐她们已经念过我很多次了。","en":"Yeah, Fanatio and the others keep telling me that, too.","ja":"散々言われてるよファナティオさんたちから"},"kind":"dialogue"},{"uid":"talk.edith_1_07#originalText","id":"talk.edith_1_07","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"伊迪丝，真羡慕妳可以自由进出这里啊。","en":"You're lucky. You get to come and go as you please.","ja":"いいよなあ、イーディスは自由に出入りができて"},"kind":"dialogue"},{"uid":"talk.edith_1_08#originalText","id":"talk.edith_1_08","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"还不是桐人你给我这个任务的。别抱怨了！","en":"Well, you were the one who gave me this position. So stop your complaining!","ja":"こういう任務を与えたのはキリトでしょ文句を言わない!"},"kind":"dialogue"},{"uid":"talk.edith_1_09#originalText","id":"talk.edith_1_09","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"知道了啦。","en":"Sure, sure.","ja":"へーい"},"kind":"dialogue"},{"uid":"talk.edith_1_10#originalText","id":"talk.edith_1_10","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"……话说回来，爱丽丝现在不知道过得怎样。","en":"Though I do wonder... how Alice is doing right now...","ja":"……それにしても、アリス今ごろ元気でやってるかな"},"kind":"dialogue"},{"uid":"talk.edith_1_10#selectionText1","id":"talk.edith_1_10","speaker":{"cn":"[1]","en":"[1]","ja":"[1]"},"text":{"cn":"搞不好每天都很辛苦","en":"Probably suffering, actually.","ja":"案外苦労してるかも"},"kind":"dialogue"},{"uid":"talk.edith_1_10#selectionText2","id":"talk.edith_1_10","speaker":{"cn":"[2]","en":"[2]","ja":"[2]"},"text":{"cn":"照爱丽丝的个性，我想应该很努力吧","en":"Knowing her, she's going strong.","ja":"アリスのことだ、しっかりやってると思うよ"},"kind":"dialogue"},{"uid":"talk.edith_1_11#originalText","id":"talk.edith_1_11","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"搞不好每天都很辛苦","en":"Probably suffering, actually.","ja":"案外苦労してるかも"},"kind":"dialogue"},{"uid":"talk.edith_1_12#originalText","id":"talk.edith_1_12","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"照爱丽丝的个性，我想应该很努力吧","en":"Knowing her, she's going strong.","ja":"アリスのことだ、しっかりやってると思うよ"},"kind":"dialogue"},{"uid":"talk.edith_1_13#originalText","id":"talk.edith_1_13","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"喂！把爱丽丝送出去的人不是你吗！","en":"Hey! You were the one who sent her out, remember?!","ja":"ちょっと!アリスを送り出したのはキリトでしょ!"},"kind":"dialogue"},{"uid":"talk.edith_1_14#originalText","id":"talk.edith_1_14","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"什么嘛！居然说她会很辛苦！","en":"How can you say, \"she's suffering\" so callously?!","ja":"なによ、苦労してるって!"},"kind":"dialogue"},{"uid":"talk.edith_1_15#originalText","id":"talk.edith_1_15","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"那边可是不同的世界，多少会有些挫折吧……","en":"Well, uh, I just figured since she's in a different world, she'd be having a hard time...","ja":"いや、世界が違うし少しは大変なことも……"},"kind":"dialogue"},{"uid":"talk.edith_1_16#originalText","id":"talk.edith_1_16","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我不能接受！我绝对不能让这种事情发生！","en":"I won't allow it! I won't let her suffer!","ja":"許さない!そんなことは許されないんだから!"},"kind":"dialogue"},{"uid":"talk.edith_1_17#originalText","id":"talk.edith_1_17","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"桐人，你现在马上把我送到另一个世界去！","en":"Kirito, send me to the other world at once!","ja":"キリト、今すぐあたしを向こうの世界に送りなさい!"},"kind":"dialogue"},{"uid":"talk.edith_1_18#originalText","id":"talk.edith_1_18","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"呃，那种事我办不到……","en":"Uh, that's impossible...","ja":"いや、無理だよそれは……"},"kind":"dialogue"},{"uid":"talk.edith_1_19#originalText","id":"talk.edith_1_19","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"管你办不办得到，快送我过去！爱丽丝，妳再等我一下！","en":"Then make it possible and send me! Wait for me, Alice!","ja":"無理でも何でも、送りなさい!アリス、待っててね!"},"kind":"dialogue"},{"uid":"talk.edith_1_20#originalText","id":"talk.edith_1_20","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我马上就去救妳了！桐人，你快点啦！","en":"I'm coming to rescue you right away! Come on, Kirito, move it!","ja":"今あたしが助けに行ってあげるから!ほら、キリト早く!"},"kind":"dialogue"},{"uid":"talk.edith_1_21#originalText","id":"talk.edith_1_21","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"说得也是。那孩子的内心可是很坚强的。","en":"True. She's got a good head on her shoulders.","ja":"そうだよねあの子、芯はしっかりしてるし"},"kind":"dialogue"},{"uid":"talk.edith_1_22#originalText","id":"talk.edith_1_22","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"不过……好想快点见到她啊。","en":"But...I sure miss her.","ja":"でも……早く会いたいなあ"},"kind":"dialogue"},{"uid":"talk.edith_1_23#originalText","id":"talk.edith_1_23","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我也想见她呀。我想听她说说，在那边过着什么样的生活。","en":"I miss her too. And I want to know what kind of life she's having on the other side.","ja":"俺も会いたいよ向こうでどんな生活を送ってるのか聞きたい"},"kind":"dialogue"},{"uid":"talk.edith_1_24#originalText","id":"talk.edith_1_24","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"对了，你、我和爱丽丝，我们三个人好像没怎么一起聊过天耶。","en":"Come to think of it, you, Alice, and I have never really sat down and talked before.","ja":"そう言えば、あんたとアリスとあたし3人で一緒に話したことって、あんまりなかったわね"},"kind":"dialogue"},{"uid":"talk.edith_1_25#originalText","id":"talk.edith_1_25","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"是吗？啊，好像是耶……","en":"Haven't we? Oh, you're right...","ja":"そうだったっけ?あ、確かに……"},"kind":"dialogue"},{"uid":"talk.edith_1_26#originalText","id":"talk.edith_1_26","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"真想找个机会坐下来好好聊聊呢。","en":"I'd love to have a proper chat at least once.","ja":"一度くらい、しっかり腰を据えて話してみたいわね"},"kind":"dialogue"},{"uid":"talk.edith_1_27#originalText","id":"talk.edith_1_27","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"尤其是亚丝娜大人的事。","en":"Especially about Lady Asuna.","ja":"特に、アスナ様のこととか"},"kind":"dialogue"},{"uid":"talk.edith_1_28#originalText","id":"talk.edith_1_28","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"啊，亚丝娜……妳到底想聊什么啊？","en":"A-Asuna? Why would you want to talk about her?","ja":"あ、アスナのこと……一体何を話すんだよ"},"kind":"dialogue"},{"uid":"talk.edith_1_29#originalText","id":"talk.edith_1_29","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"你明明心里有数，我可不准你装傻。","en":"Like you don't know. Please, even you can't be that stupid.","ja":"わかってるくせに知らないとは言わせないわよ"},"kind":"dialogue"},{"uid":"talk.edith_1_29#selectionText1","id":"talk.edith_1_29","speaker":{"cn":"[1]","en":"[1]","ja":"[1]"},"text":{"cn":"不不不，我是真的不知道～那我就先告辞啰～","en":"No, I really don't know. Anyway, bye!","ja":"いやいや、よくわからないなーそれじゃ、失礼しまーす"},"kind":"dialogue"},{"uid":"talk.edith_1_29#selectionText2","id":"talk.edith_1_29","speaker":{"cn":"[2]","en":"[2]","ja":"[2]"},"text":{"cn":"这……可是，亚丝娜是我的……","en":"Well... But Asuna is my...","ja":"それは……でもアスナは俺の……"},"kind":"dialogue"},{"uid":"talk.edith_1_30#originalText","id":"talk.edith_1_30","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"不不不，我是真的不知道～那我就先告辞啰～","en":"No, I really don't know. Anyway, bye!","ja":"いやいや、よくわからないなーそれじゃ、失礼しまーす"},"kind":"dialogue"},{"uid":"talk.edith_1_31#originalText","id":"talk.edith_1_31","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"这……可是，亚丝娜是我的……","en":"Well... But Asuna is my...","ja":"それは……でもアスナは俺の……"},"kind":"dialogue"},{"uid":"talk.edith_1_32#originalText","id":"talk.edith_1_32","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"喂！你别想逃！给我站住，桐人！","en":"Hey, don't run away! Come back, Kirito!","ja":"こら、逃げるな!待ちなさいキリト!"},"kind":"dialogue"},{"uid":"talk.edith_1_33#originalText","id":"talk.edith_1_33","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"你别以为自己逃得出本小姐的手掌心！","en":"You think you can escape from me? Fat chance!","ja":"このあたしから逃げられるなんて思わないことね!"},"kind":"dialogue"},{"uid":"talk.edith_1_34#originalText","id":"talk.edith_1_34","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"饶、饶了我吧！","en":"G-Give me a break!","ja":"か、勘弁してくれ!"},"kind":"dialogue"},{"uid":"talk.edith_1_35#originalText","id":"talk.edith_1_35","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"给我等一下──！","en":"Hold it right there!","ja":"待てー!"},"kind":"dialogue"},{"uid":"talk.edith_1_36#originalText","id":"talk.edith_1_36","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"呵呵，我就是想听你亲口说说，关于你和她的事。","en":"Hehe. I'd love to hear more from you on that subject. Much more.","ja":"ふふ、そのあたりを、たっぷりとあんたの口から聞きたいの"},"kind":"dialogue"},{"uid":"talk.edith_1_37#originalText","id":"talk.edith_1_37","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"这里的人都比较客气，所以不会主动去问。","en":"Everyone else here is too polite to ask.","ja":"ここの人たちは、遠慮してあんまり聞かないけどね"},"kind":"dialogue"},{"uid":"talk.edith_1_38#originalText","id":"talk.edith_1_38","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"那妳能不能也客气点啊……","en":"Then why can't you just be polite like them...?","ja":"だったらイーディスも遠慮してくれよ……"},"kind":"dialogue"},{"uid":"talk.edith_1_39#originalText","id":"talk.edith_1_39","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"哼哼，这么客气哪像是我啊。","en":"Nice try. If I were polite, then I'd no longer be myself.","ja":"ふふーんそんなことしたら、あたしじゃなくなっちゃうでしょ"},"kind":"dialogue"},{"uid":"talk.edith_1_40#originalText","id":"talk.edith_1_40","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"这么说是没错啦……","en":"You've got a point there.","ja":"確かにそうだけど……"},"kind":"dialogue"},{"uid":"talk.edith_1_41#originalText","id":"talk.edith_1_41","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"不过，先把玩笑话放在一边……我是真的想和大家好好聊一聊。","en":"But all joking aside... I really would like to have a nice conversation with everyone.","ja":"でも、それは冗談としても……やっぱりみんなでゆっくり話がしたいな"},"kind":"dialogue"},{"uid":"talk.edith_1_41#selectionText1","id":"talk.edith_1_41","speaker":{"cn":"[1]","en":"[1]","ja":"[1]"},"text":{"cn":"应该会是很久以后的事情了……能不能实现还很难说呢","en":"I'm not sure it'll ever happen... since that's so far in the future.","ja":"ずいぶん先の話になるから……果たして叶うかどうか"},"kind":"dialogue"},{"uid":"talk.edith_1_41#selectionText2","id":"talk.edith_1_41","speaker":{"cn":"[2]","en":"[2]","ja":"[2]"},"text":{"cn":"是呀，等爱丽丝回来，我们就好好聊聊吧","en":"Me too... After Alice returns, let's do that.","ja":"そうだな、アリスが戻ってきたら必ずやろう"},"kind":"dialogue"},{"uid":"talk.edith_1_42#originalText","id":"talk.edith_1_42","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"应该会是很久以后的事情了……能不能实现还很难说呢","en":"I'm not sure it'll ever happen... since that's so far in the future.","ja":"ずいぶん先の話になるから……果たして叶うかどうか"},"kind":"dialogue"},{"uid":"talk.edith_1_43#originalText","id":"talk.edith_1_43","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"是呀，等爱丽丝回来，我们就好好聊聊吧","en":"Me too... After Alice returns, let's do that.","ja":"そうだな、アリスが戻ってきたら必ずやろう"},"kind":"dialogue"},{"uid":"talk.edith_1_44#originalText","id":"talk.edith_1_44","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"干嘛那么没信心啊？我一定会让它实现的。","en":"Hey, negativity won't get us anywhere. I promise I'll make it happen.","ja":"そんな弱気でどうするのよ必ずかなえてみせるわ"},"kind":"dialogue"},{"uid":"talk.edith_1_45#originalText","id":"talk.edith_1_45","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"所以，桐人你最好先做好心理准备！知道了吗？","en":"So you should stay optimistic, too, Kirito! Got it?","ja":"だから、キリトもちゃんとそのつもりでいること!いいわね"},"kind":"dialogue"},{"uid":"talk.edith_1_46#originalText","id":"talk.edith_1_46","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"是，知道了……","en":"Yes, ma'am.","ja":"はい、わかりました……"},"kind":"dialogue"},{"uid":"talk.edith_1_47#originalText","id":"talk.edith_1_47","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"非常好！","en":"Good boy!","ja":"よろしい!"},"kind":"dialogue"},{"uid":"talk.edith_1_48#originalText","id":"talk.edith_1_48","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"嗯！一定哦，我们说好了！","en":"Okay! It's a promise!","ja":"うん!絶対だからね、約束!"},"kind":"dialogue"},{"uid":"talk.edith_1_49#originalText","id":"talk.edith_1_49","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"嗯，说好了。","en":"Yeah, promise.","ja":"ああ、約束だ"},"kind":"dialogue"},{"uid":"talk.edith_1_50#originalText","id":"talk.edith_1_50","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"毁约就要以违反禁忌目录来处刑喔。","en":"If you break this promise, you'll be punished for violating the Taboo Index.","ja":"これ破ったら、禁忌目録違反で処刑するから"},"kind":"dialogue"},{"uid":"talk.edith_1_51#originalText","id":"talk.edith_1_51","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"什么！？说是违反禁忌目录也太夸张了吧……","en":"Wh-What?! That's a little extreme...","ja":"ええっ!?禁忌目録違反って、そんな……"},"kind":"dialogue"},{"uid":"talk.edith_1_52#originalText","id":"talk.edith_1_52","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"意思就是要你有这种程度的觉悟。别担心，我会保护你免于危险的。","en":"Just saying you need to have that mentality. Don't worry, I'll protect you from any danger.","ja":"そのくらいの覚悟でいなさいってこと大丈夫、危険からはあたしが守ってあげるから"},"kind":"dialogue"},{"uid":"talk.edith_1_53#originalText","id":"talk.edith_1_53","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"这话还真可靠啊……","en":"I guess that makes me feel a wee bit better.","ja":"それは心強いけど……"},"kind":"dialogue"},{"uid":"talk.edith_1_54#originalText","id":"talk.edith_1_54","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"不过，视情况你可能会变成我的弟弟就是了。","en":"Well, depending on how things pan out, you might become my little brother.","ja":"まあ、場合によっては、あんたはあたしの弟になるかもしれないんだもんね"},"kind":"dialogue"},{"uid":"talk.edith_1_55#originalText","id":"talk.edith_1_55","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"啊？弟弟？","en":"Uh...little brother?","ja":"は、弟?"},"kind":"dialogue"},{"uid":"talk.edith_1_56#originalText","id":"talk.edith_1_56","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"没什么～好，那我要出门了～！","en":"Never minnnd! Anyway, I'm heading out now!","ja":"なんでもなーいそれじゃ、出かけてきまーす!"},"kind":"dialogue"},{"uid":"talk.edith_2_00#originalText","id":"talk.edith_2_00","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"「梅雅丽的任性」","en":"Mary's Selfishness","ja":"「メアリのわがまま」"},"kind":"caption"},{"uid":"talk.edith_2_01#originalText","id":"talk.edith_2_01","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"姊姊，妳今天会一直待在家里吗？","en":"Tell me, Eydis, are you going to be home all day?","ja":"ねえお姉ちゃん今日はずっと家にいるの?"},"kind":"dialogue"},{"uid":"talk.edith_2_02#originalText","id":"talk.edith_2_02","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"真受不了梅雅丽妳耶，同样的问题到底要问几次呀？","en":"Oh, Mary, how many times are you going to ask?","ja":"もう、メアリったら何回同じ事を聞くの?"},"kind":"dialogue"},{"uid":"talk.edith_2_03#originalText","id":"talk.edith_2_03","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"放心，这整个月我都不会离开，会一直在家里陪妳。","en":"Don't worry. I'm staying home all day with my Mary. I'm not going anywhere.","ja":"大丈夫、今月はずっとお出かけせずにメアリと一緒にいるわ"},"kind":"dialogue"},{"uid":"talk.edith_2_04#originalText","id":"talk.edith_2_04","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"真的吗？太好了……","en":"You mean it? Oh, good.","ja":"ほんと?よかったあ……"},"kind":"dialogue"},{"uid":"talk.edith_2_05#originalText","id":"talk.edith_2_05","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"那今天我就来煮顿大餐吧！食材也由我负责去买！","en":"I'll cook us a feast! I'll do the shopping, too!","ja":"じゃあ、今日はご馳走作るね!買い物にも、わたしが行くから!"},"kind":"dialogue"},{"uid":"talk.edith_2_06#originalText","id":"talk.edith_2_06","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"啊，我也陪妳一起去吧。我们一起去挑食材？","en":"Oh? Then I'm coming with you. Want to pick out dinner ingredients together?","ja":"あ、あたしも一緒に行くよふたりでご飯の材料選ぼう?"},"kind":"dialogue"},{"uid":"talk.edith_2_07#originalText","id":"talk.edith_2_07","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"嗯！","en":"Okay!","ja":"うん!"},"kind":"dialogue"},{"uid":"talk.edith_2_08#originalText","id":"talk.edith_2_08","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"啊！有人在卖鱼耶。说是今天早上才捕获的新鲜鱼货。","en":"Ooh! They're selling fish. From this morning's catch.","ja":"あっ、魚が売ってるね今朝の漁で獲れたんだって"},"kind":"dialogue"},{"uid":"talk.edith_2_09#originalText","id":"talk.edith_2_09","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"鱼……","en":"Fish...","ja":"お魚……"},"kind":"dialogue"},{"uid":"talk.edith_2_10#originalText","id":"talk.edith_2_10","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"怎么了，梅雅丽？妳想说什么吗？","en":"What's wrong, Mary? Are you trying to tell me something?","ja":"どうしたの、メアリ?なにか言いたいの?"},"kind":"dialogue"},{"uid":"talk.edith_2_10#selectionText1","id":"talk.edith_2_10","speaker":{"cn":"[1]","en":"[1]","ja":"[1]"},"text":{"cn":"嗯，我今天不想吃鱼，比较想吃肉","en":"Well, uh, I was hoping to cook meat for the feast instead of fish.","ja":"あの、お魚じゃなくて今日はお肉でご馳走がいいな"},"kind":"dialogue"},{"uid":"talk.edith_2_10#selectionText2","id":"talk.edith_2_10","speaker":{"cn":"[2]","en":"[2]","ja":"[2]"},"text":{"cn":"……没什么","en":"It's nothing.","ja":"……なんでもない"},"kind":"dialogue"},{"uid":"talk.edith_2_11#originalText","id":"talk.edith_2_11","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"嗯，我今天不想吃鱼，比较想吃肉","en":"Well, uh, I was hoping to cook meat for the feast instead of fish.","ja":"あの、お魚じゃなくて今日はお肉でご馳走がいいな"},"kind":"dialogue"},{"uid":"talk.edith_2_12#originalText","id":"talk.edith_2_12","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"……没什么","en":"It's nothing.","ja":"……なんでもない"},"kind":"dialogue"},{"uid":"talk.edith_2_13#originalText","id":"talk.edith_2_13","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"真的没什么吗？","en":"Are you sure it's nothing?","ja":"ホントに何でもないの?"},"kind":"dialogue"},{"uid":"talk.edith_2_14#originalText","id":"talk.edith_2_14","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"……嗯。","en":"Yeah...","ja":"……うん"},"kind":"dialogue"},{"uid":"talk.edith_2_15#originalText","id":"talk.edith_2_15","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"是吗……今天妳就尽情撒娇也可以啊。","en":"Okay... But really, you can tell me. Today of all days you should let me dote on you.","ja":"そっか……今日くらい、甘えていいのにな"},"kind":"dialogue"},{"uid":"talk.edith_2_16#originalText","id":"talk.edith_2_16","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"好、好啦！我们买鱼回去吧！","en":"C-Come on! Let's buy the fish and go home!","ja":"ほ、ほら!お魚買って帰ろう!"},"kind":"dialogue"},{"uid":"talk.edith_2_17#originalText","id":"talk.edith_2_17","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"知道啦。","en":"Okay, okay.","ja":"はいはい"},"kind":"dialogue"},{"uid":"talk.edith_2_18#originalText","id":"talk.edith_2_18","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"咦？妳想吃肉吗？那我们去对面那家店吧。","en":"Oh, you'd rather have meat? Then let's go to that other shop over there.","ja":"え、お肉がいいの?なら向こうのお店に行こうよ"},"kind":"dialogue"},{"uid":"talk.edith_2_19#originalText","id":"talk.edith_2_19","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"……姊姊，妳不生气吗？我提了那么任性的要求。","en":"Eydis... You're not mad at me? I'm being so selfish.","ja":"……お姉ちゃん、怒らないの?わたし、わがまま言ったのに"},"kind":"dialogue"},{"uid":"talk.edith_2_20#originalText","id":"talk.edith_2_20","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"妳这不是任性，只是提了想吃的东西而已。","en":"You weren't being selfish. You were just being honest about what you like.","ja":"今のはわがままじゃなくてご飯の好みでしょ?"},"kind":"dialogue"},{"uid":"talk.edith_2_21#originalText","id":"talk.edith_2_21","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"是、是这样吗……？","en":"Y-You really think so?","ja":"そ、そうかなあ……"},"kind":"dialogue"},{"uid":"talk.edith_2_22#originalText","id":"talk.edith_2_22","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"好啦，去那边买肉吧！希望能买到好吃的肉！","en":"Come on, the meat's over there! I hope they have something good!","ja":"ほら、お肉はあっち!おいしいの、あるといいね!"},"kind":"dialogue"},{"uid":"talk.edith_2_23#originalText","id":"talk.edith_2_23","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"那我去煮菜啰。妳等一下哦，姊姊。","en":"Okay, Eydis, you just relax and I'll cook supper.","ja":"それじゃ、料理するねちょっと待ってて、お姉ちゃん"},"kind":"dialogue"},{"uid":"talk.edith_2_24#originalText","id":"talk.edith_2_24","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"嗯！梅雅丽做的菜最好吃了！","en":"Sure thing! You're such a good cook!","ja":"うん!メアリの料理はおいしいからね!"},"kind":"dialogue"},{"uid":"talk.edith_2_25#originalText","id":"talk.edith_2_25","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"呵呵，今天我会煮得特别好吃的。","en":"Hehe. Well, today's feast is going to be especially delicious.","ja":"ふふ、今日のは特においしく作るから"},"kind":"dialogue"},{"uid":"talk.edith_2_26#originalText","id":"talk.edith_2_26","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"嗯，我很期待！啊～肚子饿了啦！","en":"Good, I can't wait! Ohhh, I'm hungry already!","ja":"うん、楽しみにしてる!あーお腹空いたなあ!"},"kind":"dialogue"},{"uid":"talk.edith_2_27#originalText","id":"talk.edith_2_27","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"好，煮好啰。姊姊，帮我把盘子端出去。","en":"It's ready, Eydis. Could you get some plates?","ja":"はい、できたよお姉ちゃん、お皿持ってって"},"kind":"dialogue"},{"uid":"talk.edith_2_28#originalText","id":"talk.edith_2_28","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"好～！哇！看起来好好吃！","en":"Yes, ma'am! Ooh, that smells so good!","ja":"はーい!うわ、おいしそう!"},"kind":"dialogue"},{"uid":"talk.edith_2_29#originalText","id":"talk.edith_2_29","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"梅雅丽真的很会做菜耶。妳是我最棒的妹妹。","en":"You really are an amazing cook, Mary. Couldn't be prouder.","ja":"メアリは、本当に料理上手だねえ自慢の妹だよ"},"kind":"dialogue"},{"uid":"talk.edith_2_30#originalText","id":"talk.edith_2_30","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"呵呵……没那回事啦。","en":"Hehe...oh, I'm not that great.","ja":"ふふ……そんなことないけど"},"kind":"dialogue"},{"uid":"talk.edith_2_31#originalText","id":"talk.edith_2_31","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"有！绝对有！","en":"But you are! You most definitely are!","ja":"いや、ある!そんなことあるよ!"},"kind":"dialogue"},{"uid":"talk.edith_2_32#originalText","id":"talk.edith_2_32","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"真、真是的……别说了，快吃吧。","en":"Oh, s-stop... Let's just eat.","ja":"も、もう……いいから食べよう"},"kind":"dialogue"},{"uid":"talk.edith_2_33#originalText","id":"talk.edith_2_33","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"嗯！我开动了～","en":"Okay! Bless this feast!","ja":"うん!いただきまーす!"},"kind":"dialogue"},{"uid":"talk.edith_2_34#originalText","id":"talk.edith_2_34","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"………………","en":"......","ja":"………………"},"kind":"dialogue"},{"uid":"talk.edith_2_35#originalText","id":"talk.edith_2_35","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"咦，梅雅丽？妳不吃吗？","en":"Mary... aren't you eating any?","ja":"あれ、メアリ食べないの?"},"kind":"dialogue"},{"uid":"talk.edith_2_36#originalText","id":"talk.edith_2_36","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"啊，妳是不是累了？还是脚会痛……","en":"Oh no, are you tired? Or does your leg hurt...?","ja":"あ、もしかして疲れちゃった?それとも脚が痛かったり……"},"kind":"dialogue"},{"uid":"talk.edith_2_37#originalText","id":"talk.edith_2_37","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"啊，不是啦……","en":"Oh, no, it's not that.","ja":"あ、違うんだけど……"},"kind":"dialogue"},{"uid":"talk.edith_2_37#selectionText1","id":"talk.edith_2_37","speaker":{"cn":"[1]","en":"[1]","ja":"[1]"},"text":{"cn":"我、我想要姊姊喂我吃","en":"I want...you to spoonfeed me.","ja":"あ、あーんしてほしいな"},"kind":"dialogue"},{"uid":"talk.edith_2_37#selectionText2","id":"talk.edith_2_37","speaker":{"cn":"[2]","en":"[2]","ja":"[2]"},"text":{"cn":"……没什么","en":"It's nothing.","ja":"……なんでもない"},"kind":"dialogue"},{"uid":"talk.edith_2_38#originalText","id":"talk.edith_2_38","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"我、我想要姊姊喂我吃","en":"I want...you to spoonfeed me.","ja":"あ、あーんしてほしいな"},"kind":"dialogue"},{"uid":"talk.edith_2_39#originalText","id":"talk.edith_2_39","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"……没什么","en":"It's nothing.","ja":"……なんでもない"},"kind":"dialogue"},{"uid":"talk.edith_2_40#originalText","id":"talk.edith_2_40","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"什么？我没听清楚，梅雅丽。","en":"What's that? Can't hear you.","ja":"なに、聞こえないよメアリ"},"kind":"dialogue"},{"uid":"talk.edith_2_41#originalText","id":"talk.edith_2_41","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"我说没什么。我、我开动了～！","en":"I said it's nothing. I-I'm eating now!","ja":"なんでもないって言ったのい、いただきまーす!"},"kind":"dialogue"},{"uid":"talk.edith_2_42#originalText","id":"talk.edith_2_42","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"真的吗……？","en":"Was it really nothing?","ja":"ほんとかなあ……"},"kind":"dialogue"},{"uid":"talk.edith_2_43#originalText","id":"talk.edith_2_43","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"真的！好啦，姊姊，我们开动吧。","en":"Yes, really! Come on, let's eat.","ja":"ほんとだよ!ほら、食べようお姉ちゃん"},"kind":"dialogue"},{"uid":"talk.edith_2_44#originalText","id":"talk.edith_2_44","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"梅雅丽说没什么，就没什么吧……","en":"If that's what you want, Mary...","ja":"メアリがいいならそれでいいけどさ……"},"kind":"dialogue"},{"uid":"talk.edith_2_45#originalText","id":"talk.edith_2_45","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"哎呀，这样啊？那我就喂妳吧！","en":"Oh, really? Okay then, open wide!","ja":"あら、そうなの?それじゃ、食べさせてあげる!"},"kind":"dialogue"},{"uid":"talk.edith_2_46#originalText","id":"talk.edith_2_46","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"我、我明明不是小孩子了……都这么大了，妳还愿意喂我吗？","en":"B-But I'm not a baby... I'm big now. Are you sure you're okay with this?","ja":"こ、子どもじゃないのに……もう大きいのに、いいの?"},"kind":"dialogue"},{"uid":"talk.edith_2_47#originalText","id":"talk.edith_2_47","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我的梅雅丽哪里大了，还是我小小的妹妹唷。","en":"You're not big, Mary. You're still my baby sister. And you always will be.","ja":"大きくないわ、まだまだ小さい妹よあたしのメアリは"},"kind":"dialogue"},{"uid":"talk.edith_2_48#originalText","id":"talk.edith_2_48","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"来，嘴巴张开，啊～","en":"Say ahh.","ja":"はい、あーん"},"kind":"dialogue"},{"uid":"talk.edith_2_49#originalText","id":"talk.edith_2_49","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"啊、啊～","en":"A-Ahh.","ja":"あ、あーん……"},"kind":"dialogue"},{"uid":"talk.edith_2_50#originalText","id":"talk.edith_2_50","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"怎么样？好吃吗？","en":"Well? Is it good?","ja":"どう、おいしい?"},"kind":"dialogue"},{"uid":"talk.edith_2_51#originalText","id":"talk.edith_2_51","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"嗯，超好吃。","en":"Yes, very good.","ja":"うん、すっごくおいしい"},"kind":"dialogue"},{"uid":"talk.edith_2_52#originalText","id":"talk.edith_2_52","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"是吧！好吃吧！毕竟是妳做的嘛！","en":"Of course it's good! You cooked it!","ja":"ね、おいしいよね!メアリの作ったゴハンだもん!"},"kind":"dialogue"},{"uid":"talk.edith_2_53#originalText","id":"talk.edith_2_53","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"而且还是和姊姊一起……","en":"And...we're together.","ja":"お姉ちゃんと、一緒だし……"},"kind":"dialogue"},{"uid":"talk.edith_2_54#originalText","id":"talk.edith_2_54","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"嗯，那也是原因之一。真的很开心呢，梅雅丽！","en":"Yep, that's part of it. I'm having so much fun, Mary!","ja":"うん、それもある楽しいね、メアリ!"},"kind":"dialogue"},{"uid":"talk.edith_2_55#originalText","id":"talk.edith_2_55","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"嗯。","en":"Me too.","ja":"うん"},"kind":"dialogue"},{"uid":"talk.edith_2_56#originalText","id":"talk.edith_2_56","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"啊～太好吃了！多谢款待！","en":"Ahh, that was so yummy! My compliments to the chef.","ja":"あーおいしかった!ごちそうさま!"},"kind":"dialogue"},{"uid":"talk.edith_2_57#originalText","id":"talk.edith_2_57","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"真的很好吃呢，姊姊。","en":"It really was tasty.","ja":"おいしかったね、お姉ちゃん"},"kind":"dialogue"},{"uid":"talk.edith_2_58#originalText","id":"talk.edith_2_58","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"嗯，我吃饱了……呐，梅雅丽……我们直接去睡吧。","en":"Yep, I'm stuffed... Hey, Mary... Wanna just go to bed?","ja":"うん、お腹いっぱい……ねえ、メアリ……このまま寝ちゃおうか"},"kind":"dialogue"},{"uid":"talk.edith_2_59#originalText","id":"talk.edith_2_59","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"吃得饱饱的上床睡觉，一定很舒服～","en":"I think flopping in bed right after a satisfying meal would really hit the spot.","ja":"お腹いっぱいのままベッドに入ったらきっと気持ちいいと思うんだー"},"kind":"dialogue"},{"uid":"talk.edith_2_59#selectionText1","id":"talk.edith_2_59","speaker":{"cn":"[1]","en":"[1]","ja":"[1]"},"text":{"cn":"不行，得好好收拾才行。一起来收拾吧，姊姊","en":"No, we have to clean up first. Let's do it together, Eydis.","ja":"ダメ、ちゃんと片付けないと一緒に片付けよう、お姉ちゃん"},"kind":"dialogue"},{"uid":"talk.edith_2_59#selectionText2","id":"talk.edith_2_59","speaker":{"cn":"[2]","en":"[2]","ja":"[2]"},"text":{"cn":"那姊姊就先去睡吧，剩下的交给我来收拾","en":"You can go to bed first. I'll handle the washing up.","ja":"だったら、お姉ちゃんは寝ていいよあとはわたしがやっておくから"},"kind":"dialogue"},{"uid":"talk.edith_2_60#originalText","id":"talk.edith_2_60","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"不行，得好好收拾才行。一起来收拾吧，姊姊","en":"No, we have to clean up first. Let's do it together, Eydis.","ja":"ダメ、ちゃんと片付けないと一緒に片付けよう、お姉ちゃん"},"kind":"dialogue"},{"uid":"talk.edith_2_61#originalText","id":"talk.edith_2_61","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"那姊姊就先去睡吧，剩下的交给我来收拾","en":"You can go to bed first. I'll handle the washing up.","ja":"だったら、お姉ちゃんは寝ていいよあとはわたしがやっておくから"},"kind":"dialogue"},{"uid":"talk.edith_2_62#originalText","id":"talk.edith_2_62","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"啊，梅雅丽不一起去睡就没意思啦！走啦，一起去睡觉嘛！","en":"Wait, that won't do, Mary! It's pointless if you don't join me! Come on, let's go to bed.","ja":"あ、メアリが寝ないと意味ないんだよ!ほら、寝ようよ"},"kind":"dialogue"},{"uid":"talk.edith_2_63#originalText","id":"talk.edith_2_63","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"不行，得先收拾才行。","en":"No, I have to wash up.","ja":"ダメだよ、後片付けはしないと"},"kind":"dialogue"},{"uid":"talk.edith_2_64#originalText","id":"talk.edith_2_64","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"欸～有什么关系嘛！","en":"Aww, come on!","ja":"えー、いいじゃない!"},"kind":"dialogue"},{"uid":"talk.edith_2_65#originalText","id":"talk.edith_2_65","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"不～行。来，姊姊擦干后就收起来吧。","en":"No. Here, Eydis, you can dry the dishes.","ja":"ダーメはい、お姉ちゃんは拭いてしまってね"},"kind":"dialogue"},{"uid":"talk.edith_2_66#originalText","id":"talk.edith_2_66","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"唉，真是败给妳了……","en":"Argh... Well, if I must.","ja":"はあ、仕方ないかあ……"},"kind":"dialogue"},{"uid":"talk.edith_2_67#originalText","id":"talk.edith_2_67","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我就知道会这样。","en":"I suppose you're right.","ja":"やっぱりそうだよね"},"kind":"dialogue"},{"uid":"talk.edith_2_68#originalText","id":"talk.edith_2_68","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"嗯，两个人一起做，两三下就解决了。","en":"Yeah. We'll finish in no time if we work together.","ja":"うんふたりでやれば、すぐに終わるよ"},"kind":"dialogue"},{"uid":"talk.edith_2_69#originalText","id":"talk.edith_2_69","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"那我们等等一起去洗澡吧。我帮妳洗头。","en":"Then we'll take a bath together! I can wash your hair for you.","ja":"そうしたら、一緒にお風呂入ろうか髪洗ってあげる"},"kind":"dialogue"},{"uid":"talk.edith_2_70#originalText","id":"talk.edith_2_70","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"嗯！啊，我也想帮姊姊洗头！","en":"Okay! Ooh, I wanna wash your hair, too!","ja":"うん! あ、わたしもお姉ちゃんの髪洗いたい!"},"kind":"dialogue"},{"uid":"talk.edith_2_71#originalText","id":"talk.edith_2_71","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"咦？妳要帮我洗头吗？那得多放一点洗澡水啰！","en":"Oh, would you? We'd better heat up plenty of water for that!","ja":"え、洗ってくれるの?だったら、たくさんお湯溜めないとね!"},"kind":"dialogue"},{"uid":"talk.edith_2_72#originalText","id":"talk.edith_2_72","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"虽然有点费事……不过今天就特别帮妳服务！","en":"Sounds like a lot of work... But today is a special day!","ja":"ちょっと大変だけど……今日は特別だから!"},"kind":"dialogue"},{"uid":"talk.edith_2_73#originalText","id":"talk.edith_2_73","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"好～那就快点收拾干净吧！","en":"Okayyy, let's get this washing up done fast!","ja":"よーし、片付けはさっさと終わらせちゃおう!"},"kind":"dialogue"},{"uid":"talk.edith_2_74#originalText","id":"talk.edith_2_74","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"洗完澡好舒服哦，姊姊。","en":"That really felt great, Eydis.","ja":"気持ちよかったね、お姉ちゃん"},"kind":"dialogue"},{"uid":"talk.edith_2_75#originalText","id":"talk.edith_2_75","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"嗯，谢谢妳帮我洗头，梅雅丽。","en":"Yes. Thanks for washing my hair, Mary.","ja":"うん髪洗ってくれてありがと、メアリ"},"kind":"dialogue"},{"uid":"talk.edith_2_76#originalText","id":"talk.edith_2_76","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"明天姊姊居然也在家，总觉得好开心哦。","en":"Knowing I'll have you to myself again tomorrow makes me feel all giddy inside.","ja":"明日もお姉ちゃんがいるなんてなんだかうれしいなあ"},"kind":"dialogue"},{"uid":"talk.edith_2_77#originalText","id":"talk.edith_2_77","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"可以陪在妳身边，我也很开心。","en":"Me too, Mary. I love spending time with you.","ja":"あたしもうれしいメアリと一緒にいられて"},"kind":"dialogue"},{"uid":"talk.edith_2_78#originalText","id":"talk.edith_2_78","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"好，那么我们就一起去睡，好迎接明天的到来吧。","en":"Okay, let's prepare for the new day by getting some good shut-eye together!","ja":"よし、じゃあ明日に備えて一緒に寝ようか"},"kind":"dialogue"},{"uid":"talk.edith_2_79#originalText","id":"talk.edith_2_79","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"嗯！","en":"Okay!","ja":"うん!"},"kind":"dialogue"},{"uid":"talk.edith_3_00#originalText","id":"talk.edith_3_00","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"「到远处飞一趟」","en":"Long Journey","ja":"「遠乗り」"},"kind":"caption"},{"uid":"talk.edith_3_01#originalText","id":"talk.edith_3_01","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"雨缘，妳怎么了？冷静一点！","en":"What's wrong, Amayori? Behave yourself!","ja":"雨縁、どうしたのですか?大人しくしなさい!"},"kind":"dialogue"},{"uid":"talk.edith_3_02#originalText","id":"talk.edith_3_02","speaker":{"cn":"雨缘","en":"Amayori","ja":"雨縁"},"text":{"cn":"啾噜噜噜！！","en":"Krrrrrr!","ja":"キュルルルッ!!"},"kind":"dialogue"},{"uid":"talk.edith_3_03#originalText","id":"talk.edith_3_03","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"爱丽丝，怎么吵吵闹闹的？","en":"What's wrong, Alice? It's awfully noisy out here.","ja":"どうしたの、アリス?ずいぶん騒がしいけど"},"kind":"dialogue"},{"uid":"talk.edith_3_04#originalText","id":"talk.edith_3_04","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"伊迪丝阁下……我在帮雨缘洗身体，但牠好像不太高兴。","en":"Eydis... I was giving Amayori a bath, but she seems to be in a foul mood.","ja":"イーディス殿……雨縁の体を洗っていたのですが機嫌が悪いみたいで"},"kind":"dialogue"},{"uid":"talk.edith_3_04#selectionText1","id":"talk.edith_3_04","speaker":{"cn":"[1]","en":"[1]","ja":"[1]"},"text":{"cn":"是吗？加油喔。照顾飞龙也是集成骑士的工作之一","en":"So that's what it was. Well, good luck. Caring for our dragons is part of the job.","ja":"そうかあ、頑張ってね飛竜のお世話も、整合騎士のお仕事だし"},"kind":"dialogue"},{"uid":"talk.edith_3_04#selectionText2","id":"talk.edith_3_04","speaker":{"cn":"[2]","en":"[2]","ja":"[2]"},"text":{"cn":"原来如此……要是妳不嫌弃，我来帮帮妳吧？","en":"Ah-hah... Would you like some help?","ja":"なるほどね……よかったら、少し手伝おうか?"},"kind":"dialogue"},{"uid":"talk.edith_3_05#originalText","id":"talk.edith_3_05","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"是吗？加油喔。照顾飞龙也是集成骑士的工作之一","en":"So that's what it was. Well, good luck. Caring for our dragons is part of the job.","ja":"そうかあ、頑張ってね飛竜のお世話も、整合騎士のお仕事だし"},"kind":"dialogue"},{"uid":"talk.edith_3_06#originalText","id":"talk.edith_3_06","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"原来如此……要是妳不嫌弃，我来帮帮妳吧？","en":"Ah-hah... Would you like some help?","ja":"なるほどね……よかったら、少し手伝おうか?"},"kind":"dialogue"},{"uid":"talk.edith_3_07#originalText","id":"talk.edith_3_07","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"是的……我明白。雨缘，头稍微低一点……","en":"Yes...I know. Come, Amayori, lower your head.","ja":"はい……心得ていますほら雨縁、ちょっと頭を下げて……"},"kind":"dialogue"},{"uid":"talk.edith_3_08#originalText","id":"talk.edith_3_08","speaker":{"cn":"雨缘","en":"Amayori","ja":"雨縁"},"text":{"cn":"啾噜！！","en":"Krrrrrr!","ja":"キュルッ!!"},"kind":"dialogue"},{"uid":"talk.edith_3_09#originalText","id":"talk.edith_3_09","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"啊！？喂！雨缘……","en":"C-Come on now, Amayori!","ja":"あっ!?こら雨縁……"},"kind":"dialogue"},{"uid":"talk.edith_3_10#originalText","id":"talk.edith_3_10","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"这也是修练的一环哦，爱丽丝！","en":"It's all part of your training, Alice!","ja":"これも修行のうちよ、アリス!"},"kind":"dialogue"},{"uid":"talk.edith_3_11#originalText","id":"talk.edith_3_11","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"真的吗？可是，这是我的……","en":"You mean it? Oh, but this is my duty...","ja":"本当ですか?いや、でもこれは私の……"},"kind":"dialogue"},{"uid":"talk.edith_3_12#originalText","id":"talk.edith_3_12","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"照顾雨缘的确是妳的工作。不过，从旁协助的话也没关系吧？","en":"Of course Amayori's care is your responsibility. But you wouldn't mind some help, right?","ja":"もちろん、雨縁のお世話はアリスの仕事よでも、それを手伝うのは構わないでしょう?"},"kind":"dialogue"},{"uid":"talk.edith_3_13#originalText","id":"talk.edith_3_13","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"好的……那就麻烦妳了。","en":"You're right... I humbly accept your offer.","ja":"はい……ではお願いします"},"kind":"dialogue"},{"uid":"talk.edith_3_14#originalText","id":"talk.edith_3_14","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"嗯～雨缘，妳到底怎么了……？","en":"Hmm, what's wrong, Amayori?","ja":"うーん、どうしたのかな雨縁……"},"kind":"dialogue"},{"uid":"talk.edith_3_15#originalText","id":"talk.edith_3_15","speaker":{"cn":"雨缘","en":"Amayori","ja":"雨縁"},"text":{"cn":"啾噜噜……","en":"Krrrrrr....","ja":"キュルル……"},"kind":"dialogue"},{"uid":"talk.edith_3_16#originalText","id":"talk.edith_3_16","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"啊，我知道了！这里会痒对吧！","en":"Oh, I know! You've got an itch!","ja":"あ、わかった!ここが痒いのね!"},"kind":"dialogue"},{"uid":"talk.edith_3_17#originalText","id":"talk.edith_3_17","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"就是这里对吧？舒服吗？","en":"Am I hitting the spot? Does that feel good?","ja":"ほら、ここでしょ気持ちいい?"},"kind":"dialogue"},{"uid":"talk.edith_3_18#originalText","id":"talk.edith_3_18","speaker":{"cn":"雨缘","en":"Amayori","ja":"雨縁"},"text":{"cn":"啾噜……","en":"Krrrrrr....","ja":"キュル……"},"kind":"dialogue"},{"uid":"talk.edith_3_19#originalText","id":"talk.edith_3_19","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"喔喔，雨缘安静下来了……妳是怎么知道的呢！？","en":"Wow, Amayori's settled down... How did you know?!","ja":"おお、雨縁が大人しく……どうしてわかったのですか!?"},"kind":"dialogue"},{"uid":"talk.edith_3_19#selectionText1","id":"talk.edith_3_19","speaker":{"cn":"[1]","en":"[1]","ja":"[1]"},"text":{"cn":"毕竟我当集成骑士这么久了，算是凭经验吧","en":"When you've been an Integrity Knight as long as I have, you get a feel for these things.","ja":"長いこと整合騎士やってるからね慣れでわかるの"},"kind":"dialogue"},{"uid":"talk.edith_3_19#selectionText2","id":"talk.edith_3_19","speaker":{"cn":"[2]","en":"[2]","ja":"[2]"},"text":{"cn":"这果然应该是我的才能吧！？","en":"I guess it's a talent of mine? My great talent!","ja":"やっぱり才能かしら?このあたしの!"},"kind":"dialogue"},{"uid":"talk.edith_3_20#originalText","id":"talk.edith_3_20","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"毕竟我当集成骑士这么久了，算是凭经验吧","en":"When you've been an Integrity Knight as long as I have, you get a feel for these things.","ja":"長いこと整合騎士やってるからね慣れでわかるの"},"kind":"dialogue"},{"uid":"talk.edith_3_21#originalText","id":"talk.edith_3_21","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"这果然应该是我的才能吧！？","en":"I guess it's a talent of mine? My great talent!","ja":"やっぱり才能かしら?このあたしの!"},"kind":"dialogue"},{"uid":"talk.edith_3_22#originalText","id":"talk.edith_3_22","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"才能……看来我果然没有饲育飞龙的才能……","en":"Your...talent? I suppose I lack the talent to train and nurture dragons...","ja":"才能……ですかやはり私には、飛竜を育てる才能がない……"},"kind":"dialogue"},{"uid":"talk.edith_3_23#originalText","id":"talk.edith_3_23","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"啊，不是啦！我不是说妳没有才能！","en":"Oh, no! I didn't mean that you were untalented!","ja":"あ、違うよ!アリスが才能無いとかじゃなくて!"},"kind":"dialogue"},{"uid":"talk.edith_3_24#originalText","id":"talk.edith_3_24","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"谢谢妳，但我不需要安慰。我先告辞了，伊迪丝阁下。","en":"Thank you, Eydis. But I don't need your sympathy. If you'll excuse me.","ja":"ありがとうございます、でも慰めはいりません失礼します、イーディス殿"},"kind":"dialogue"},{"uid":"talk.edith_3_25#originalText","id":"talk.edith_3_25","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"经验吗……那么我总有一天也会懂吗……","en":"You got a feel for it? Then maybe I'll get better at this someday.","ja":"慣れ……ですかそれならば、私もいつか……"},"kind":"dialogue"},{"uid":"talk.edith_3_26#originalText","id":"talk.edith_3_26","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"那还用说！妳进步的速度比我快多了。","en":"Of course you will! You've been improving much faster than I did.","ja":"もちろん!あたしなんかよりずっと成長早いわよ"},"kind":"dialogue"},{"uid":"talk.edith_3_27#originalText","id":"talk.edith_3_27","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"大家也都夸说妳很厉害啊。","en":"Everyone is very impressed.","ja":"さすがアリスだって、みんな褒めてたんだから"},"kind":"dialogue"},{"uid":"talk.edith_3_28#originalText","id":"talk.edith_3_28","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"真、真的吗？可是今天也是在妳的帮忙下才……","en":"Y-You really think so? You had to help me out just now.","ja":"ほ、本当でしょうか今日だって、イーディス殿に助けてもらって……"},"kind":"dialogue"},{"uid":"talk.edith_3_29#originalText","id":"talk.edith_3_29","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"大家一开始都一样啦。我当初也受过很多人的帮助啊。","en":"Everyone needs help at the start. I got lots of help when I was a fledgling Knight.","ja":"最初のうちは、誰だってそうだよあたしだって、たくさん助けてもらったんだから"},"kind":"dialogue"},{"uid":"talk.edith_3_30#originalText","id":"talk.edith_3_30","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"真的吗？","en":"Did you really?","ja":"そうなのですか?"},"kind":"dialogue"},{"uid":"talk.edith_3_31#originalText","id":"talk.edith_3_31","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"嗯，迪索尔巴德教会我很多事情。","en":"Yep. In my case, Deusolbert was the one who showed me the ropes.","ja":"うん。あたしに色々教えてくれたのはデュソルバートだったの"},"kind":"dialogue"},{"uid":"talk.edith_3_32#originalText","id":"talk.edith_3_32","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"迪索尔巴德阁下吗？真令人羡慕。","en":"Deusolbert...you say? You're lucky.","ja":"デュソルバート殿、ですかそれはうらやましいですね"},"kind":"dialogue"},{"uid":"talk.edith_3_32#selectionText1","id":"talk.edith_3_32","speaker":{"cn":"[1]","en":"[1]","ja":"[1]"},"text":{"cn":"会吗？其实我不太擅长应付迪索尔巴德","en":"Was I really? He's kinda hard to deal with.","ja":"そうかなあデュソルバート、ちょっと苦手なの"},"kind":"dialogue"},{"uid":"talk.edith_3_32#selectionText2","id":"talk.edith_3_32","speaker":{"cn":"[2]","en":"[2]","ja":"[2]"},"text":{"cn":"他这个人看起来是很严肃，不过意外地好聊，人也挺好的","en":"Well, he may look stern, but he's actually pretty nice once you get to know him.","ja":"まあ、ぱっと見は堅苦しいけど、案外話せるしね割と優しいし"},"kind":"dialogue"},{"uid":"talk.edith_3_33#originalText","id":"talk.edith_3_33","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"会吗？其实我不太擅长应付迪索尔巴德","en":"Was I really? He's kinda hard to deal with.","ja":"そうかなあデュソルバート、ちょっと苦手なの"},"kind":"dialogue"},{"uid":"talk.edith_3_34#originalText","id":"talk.edith_3_34","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"他这个人看起来是很严肃，不过意外地好聊，人也挺好的","en":"Well, he may look stern, but he's actually pretty nice once you get to know him.","ja":"まあ、ぱっと見は堅苦しいけど、案外話せるしね割と優しいし"},"kind":"dialogue"},{"uid":"talk.edith_3_35#originalText","id":"talk.edith_3_35","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"妳又在说些惹人厌的话……","en":"Again with your cheek...","ja":"またそんな憎まれ口を……"},"kind":"dialogue"},{"uid":"talk.edith_3_36#originalText","id":"talk.edith_3_36","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"因为人家比较喜欢可爱的女孩子嘛！","en":"Well, I'd rather learn from a pretty girl!","ja":"だって、可愛い女の子がよかったんだもん!"},"kind":"dialogue"},{"uid":"talk.edith_3_37#originalText","id":"talk.edith_3_37","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我们是集成骑士，性别和容貌一点也不重要！","en":"We are Integrity Knights. Gender and appearance are irrelevant!","ja":"我々は整合騎士です性別や容姿など、関係ありません!"},"kind":"dialogue"},{"uid":"talk.edith_3_38#originalText","id":"talk.edith_3_38","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"受不了……伊迪丝阁下总是这样……","en":"Goodness... Why are you always like this?","ja":"まったく……イーディス殿はいつもそうやって……"},"kind":"dialogue"},{"uid":"talk.edith_3_39#originalText","id":"talk.edith_3_39","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"唉唷，对不起嘛，爱丽丝！我以后会好好说话的！","en":"Aww, sorry, Alice! I'll behave, promise!","ja":"ああん、ごめんアリス!ちゃんと話すから!"},"kind":"dialogue"},{"uid":"talk.edith_3_40#originalText","id":"talk.edith_3_40","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我不管妳了！","en":"Forget it!","ja":"知りません!"},"kind":"dialogue"},{"uid":"talk.edith_3_41#originalText","id":"talk.edith_3_41","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"是的，迪索尔巴德阁下为人民着想，且以礼相待，非常值得我们学习。","en":"Yes, I do admire the kindness and courtesy Deusolbert has for the common man.","ja":"はい、デュソルバート殿の民に対する思いや礼節は見習わなければならないと思います"},"kind":"dialogue"},{"uid":"talk.edith_3_42#originalText","id":"talk.edith_3_42","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"别看他的盔甲硬梆梆的，对小孩子可是非常温柔呢。","en":"Yeah, and even though he's such a hardhead, he's really kind to children.","ja":"あんな鎧ガチガチなのに、子どもにはすっごく優しいしね"},"kind":"dialogue"},{"uid":"talk.edith_3_43#originalText","id":"talk.edith_3_43","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"是呀，要是我也能像他那样，好好教教艾尔多利耶就好了。","en":"Yes. I hope that I can be such a kind teacher for Eldrie.","ja":"はい、私もあんな風にエルドリエに対して教えてあげられればよいのですが"},"kind":"dialogue"},{"uid":"talk.edith_3_44#originalText","id":"talk.edith_3_44","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"啊，艾尔多利耶呀……","en":"Ahhh, Eldrie, eh?","ja":"あー、エルドリエね……"},"kind":"dialogue"},{"uid":"talk.edith_3_44#selectionText1","id":"talk.edith_3_44","speaker":{"cn":"[1]","en":"[1]","ja":"[1]"},"text":{"cn":"那小子已经没救了，他眼中只有妳而已","en":"He's no good. He's obsessed with you.","ja":"あの子はダメねアリスしか見てないから"},"kind":"dialogue"},{"uid":"talk.edith_3_44#selectionText2","id":"talk.edith_3_44","speaker":{"cn":"[2]","en":"[2]","ja":"[2]"},"text":{"cn":"别看他那样，他其实很痴心又拼命，私下好像做了不少努力","en":"I don't know whether to call him devoted or desperate. He seems to be doing a lot in secret.","ja":"ああ見えて、一途だったり必死だったり隠れて色々やってるみたいだけど"},"kind":"dialogue"},{"uid":"talk.edith_3_45#originalText","id":"talk.edith_3_45","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"那小子已经没救了，他眼中只有妳而已","en":"He's no good. He's obsessed with you.","ja":"あの子はダメねアリスしか見てないから"},"kind":"dialogue"},{"uid":"talk.edith_3_46#originalText","id":"talk.edith_3_46","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"别看他那样，他其实很痴心又拼命，私下好像做了不少努力","en":"I don't know whether to call him devoted or desperate. He seems to be doing a lot in secret.","ja":"ああ見えて、一途だったり必死だったり隠れて色々やってるみたいだけど"},"kind":"dialogue"},{"uid":"talk.edith_3_47#originalText","id":"talk.edith_3_47","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"没这回事！艾尔多利耶也是个了不起的集成骑士。","en":"Oh, don't say that! Eldrie is a model Integrity Knight!","ja":"そんなことはありません!エルドリエも立派な整合騎士です!"},"kind":"dialogue"},{"uid":"talk.edith_3_48#originalText","id":"talk.edith_3_48","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"伊迪丝阁下，我无法接受妳如此贬低同胞。","en":"Eydis, I cannot condone speaking so ill of one of our own!","ja":"イーディス殿、同胞をそのように悪し様に言うのは感心できません"},"kind":"dialogue"},{"uid":"talk.edith_3_49#originalText","id":"talk.edith_3_49","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"咦～可是～","en":"Awww, but come on...","ja":"えー、だってさー"},"kind":"dialogue"},{"uid":"talk.edith_3_50#originalText","id":"talk.edith_3_50","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"没有什么可是不可是！请妳收回那句话！","en":"Don't you \"Come on\" me! Retract your insult at once!","ja":"だって、じゃありません!撤回してください!"},"kind":"dialogue"},{"uid":"talk.edith_3_51#originalText","id":"talk.edith_3_51","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"是的……他也用自己的方式在努力着。我想好好支持他。","en":"Yes... I think Eldrie is working very hard. And I want to be supportive.","ja":"はい……エルドリエなりに頑張っていると思います私は、それを支えてあげたい"},"kind":"dialogue"},{"uid":"talk.edith_3_52#originalText","id":"talk.edith_3_52","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"再来就是希望他能成熟些呢～像是说话方式之类的。","en":"If only he'd tone it down a little. Like, the way he talks.","ja":"あとは、もう少し大人しくなればねーあの口の利き方とか"},"kind":"dialogue"},{"uid":"talk.edith_3_53#originalText","id":"talk.edith_3_53","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"没错……不过，如同我照顾飞龙一样，或许时间一久就会进步了。","en":"Agreed... But just like my skill with the dragons, I'm sure that will change with time.","ja":"そうですね……でも、私の飛竜の扱いと同じく時を経れば変わるのかもしれません"},"kind":"dialogue"},{"uid":"talk.edith_3_54#originalText","id":"talk.edith_3_54","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"事实上，比起一开始的时候，艾尔多利耶已经改变很多了。","en":"In fact, Eldrie has already changed quite a bit.","ja":"現に、エルドリエも最初の頃からはずいぶん変わりましたから"},"kind":"dialogue"},{"uid":"talk.edith_3_55#originalText","id":"talk.edith_3_55","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"嗯，只好发挥耐心看着他了，虽然麻烦了点。","en":"Yep. We'd better be patient with him...a hassle though that it may be.","ja":"うん、気長に面倒見てあげよう面倒くさいけど"},"kind":"dialogue"},{"uid":"talk.edith_3_56#originalText","id":"talk.edith_3_56","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"说什么麻烦……我从来没有这种想法！","en":"A hassle? I would never think of mentoring him as a hassle!","ja":"面倒だなどと……私は、そんなことは思っておりません!"},"kind":"dialogue"},{"uid":"talk.edith_3_57#originalText","id":"talk.edith_3_57","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"好啦，雨缘的心情也平静下来了，到远处飞一趟怎么样？","en":"Well, now that Amayori is in a better mood, would you like to fly somewhere?","ja":"さて、雨縁の機嫌もなおったしどこかに遠乗りでも行きましょうか"},"kind":"dialogue"},{"uid":"talk.edith_3_58#originalText","id":"talk.edith_3_58","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"雨缘也一脸想活动活动的样子。","en":"She looks like she's up for an outing.","ja":"雨縁も、なんだか動きたそうな顔してるわよ"},"kind":"dialogue"},{"uid":"talk.edith_3_59#originalText","id":"talk.edith_3_59","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"这个嘛……反正没有任务，那就走吧。","en":"Good idea... I don't have any tasks at the moment, so let's go.","ja":"そうですね……任務もないですし参りましょう"},"kind":"dialogue"},{"uid":"talk.edith_3_60#originalText","id":"talk.edith_3_60","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"这才像话嘛！那我们赶快出发吧！","en":"That's the spirit! Well, let's get going!","ja":"そう来なくっちゃ!それじゃ、急いで行きましょう!"},"kind":"dialogue"},{"uid":"talk.edith_3_61#originalText","id":"talk.edith_3_61","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"趁元老长或其他人来打搅之前！","en":"We'd better get out of here before the Prime Senator comes to bug us again!","ja":"また、元老長とかが邪魔しに来ないうちにね!"},"kind":"dialogue"},{"uid":"talk.edith_shadow_story8#originalText","id":"talk.edith_shadow_story8","speaker":{},"text":{"cn":"伊迪丝的影子出现了！","en":"Eydis's shadow appeared!","ja":"イーディスの影が出現した！"},"kind":"narration"}]};
